def audit(events, at):
    selected = {}
    for event in events:
        if event["seen"] > at:
            continue
        sides = selected.setdefault(event["key"], {})
        side = event["side"]
        epoch = event["epoch"]
        digest = event["digest"]
        current = sides.get(side)
        if current is None or epoch > current[0]:
            sides[side] = (epoch, {digest})
        elif epoch == current[0]:
            current[1].add(digest)
    result = {}
    for key, sides in selected.items():
        if any(len(value[1]) > 1 for value in sides.values()):
            result[key] = "conflict"
        elif "L" not in sides or "R" not in sides:
            result[key] = "pending"
        elif sides["L"][0] != sides["R"][0]:
            result[key] = "pending"
        elif sides["L"][1] != sides["R"][1]:
            result[key] = "diverged"
        else:
            result[key] = "verified"
    return result

